85:                 GeneratedCodeRecognizer,
86:                 c =>
87:                 {
88:                     var isInCheckedContext = new Lazy<bool>(() => IsInCheckedContext(c.Node, c.SemanticModel));
89: 
90:                     var leftNode = Language.Syntax.BinaryExpressionLeft(c.Node);
91:                     if (IsPathDelimiter(leftNode) && isInCheckedContext.Value)
92:                     {
